import{_ as e,o as s,c as i,a7 as t}from"./chunks/framework.6XcjuvSi.js";const k=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"vue2/guide/faq.md","filePath":"vue2/guide/faq.md","lastUpdated":1792782999000}'),n={name:"vue2/guide/faq.md"};function l(r,a,h,o,p,d){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="为什么页面加载后不能自动进入原生全屏" tabindex="-1">为什么页面加载后不能自动进入原生全屏？ <a class="header-anchor" href="#为什么页面加载后不能自动进入原生全屏" aria-label="Permalink to &quot;为什么页面加载后不能自动进入原生全屏？&quot;">​</a></h2><p>原生全屏<strong>只能由</strong>点击、触摸或按键等用户操作触发，这是浏览器的用户激活限制。请在事件处理函数中直接发起请求；等待网络响应或计时器后再调用，可能因用户激活状态过期而被拒绝。如果需要无需用户操作就自动放大内容，可使用 <code>pageOnly: true</code>。详见<a href="/vue2/guide/compatibility#用户操作与-iframe-权限">用户操作与 iframe 权限</a>。</p><h2 id="点击后没有进入原生全屏" tabindex="-1">点击后没有进入原生全屏？ <a class="header-anchor" href="#点击后没有进入原生全屏" aria-label="Permalink to &quot;点击后没有进入原生全屏？&quot;">​</a></h2><p>先检查错误事件或 Promise 拒绝。嵌入 iframe 时还需要宿主允许 fullscreen 权限。</p><p><code>isSupported</code> 只表示 API 可用，不保证每次请求都被批准。可先启用 <code>pageOnly</code>，排除原生权限问题。</p><h2 id="手机上的表现为什么不同" tabindex="-1">手机上的表现为什么不同？ <a class="header-anchor" href="#手机上的表现为什么不同" aria-label="Permalink to &quot;手机上的表现为什么不同？&quot;">​</a></h2><p>不同浏览器、设备及嵌入方式的原生全屏支持不同。不支持时库会降级到网页全屏；网页全屏仍保留浏览器工具栏。请在目标设备上验证，而不是根据桌面浏览器推断。</p><h2 id="弹窗或下拉菜单看不到" tabindex="-1">弹窗或下拉菜单看不到？ <a class="header-anchor" href="#弹窗或下拉菜单看不到" aria-label="Permalink to &quot;弹窗或下拉菜单看不到？&quot;">​</a></h2><p>浏览器只显示原生全屏元素及其后代，提高 <code>z-index</code> 无法显示其外部的弹窗。开启 <code>teleport</code> 并配置 UI 库将弹窗挂载到 <code>body</code>，或关闭 <code>teleport</code>、将弹窗直接挂载在全屏目标内部。可在<a href="/vue2/">快速上手</a>对比效果。</p><h2 id="teleport-后样式变了" tabindex="-1">teleport 后样式变了？ <a class="header-anchor" href="#teleport-后样式变了" aria-label="Permalink to &quot;teleport 后样式变了？&quot;">​</a></h2><p>元素从原父节点移动到了 body。依赖祖先的 CSS 选择器和继承值可能失效；把关键样式放到目标自身的 class 上。退出时会恢复原 DOM 位置和被库修改的行内布局样式。</p><p>通过 <code>fullscreenClass</code> 设置背景、滚动和层级；库不会强制设置这些样式：</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.my-fullscreen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  background</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">white</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  overflow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  z-index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="ssr-或-nuxt-可以用吗" tabindex="-1">SSR 或 Nuxt 可以用吗？ <a class="header-anchor" href="#ssr-或-nuxt-可以用吗" aria-label="Permalink to &quot;SSR 或 Nuxt 可以用吗？&quot;">​</a></h2><p>可以在服务端导入包。只在浏览器挂载后读取 DOM，并在用户操作中请求原生全屏。不要在服务端调用 <code>fullscreen.enter()</code>。</p>`,16)])])}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
